VSK_st.name='VSK'; 
VSK_st.lat=17.69;
VSK_st.lon=83.29;
VSK_st.alt=0000;
VSK_st.env='Coas';
VSK_st.footp='RB';
%%
% data imported via the import tool from matlab
 VSK_rd_h = importfile_AE_India("C:\github_trend\raw_data\Aethalometer_India\Aethalometer\VSK_2016-2026_Hour.csv", [2, Inf]);
VSK_rd_h.Properties.DimensionNames{1}='Time';
VSK_rd_h.Properties.VariableNames{2}='Ba1_A';
VSK_rd_h.Properties.VariableNames{3}='Ba2_A';
VSK_rd_h.Properties.VariableNames{4}='Ba3_A';
VSK_rd_h.Properties.VariableNames{5}='Ba4_A';
VSK_rd_h.Properties.VariableNames{6}='Ba5_A';
VSK_rd_h.Properties.VariableNames{7}='Ba6_A';
VSK_rd_h.Properties.VariableNames{8}='Ba7_A';
names_rd=fieldnames(VSK_rd_h);
%%
VSK_rd=retime(VSK_rd_h,'daily',@nanmedian);
%%
datevec(VSK_rd.Time(1)) % begin in 2016,  %[output:7a3f5d0a]
datevec(VSK_rd.Time(end)) % end in 2019 May %[output:0c280ed0]
plotFigControl(VSK_rd,VSK_st.name);  %[output:7030742d] %[output:92f916c9] %[output:8a3db4cb] %[output:0941217c] %[output:81f161b9] %[output:7911ff20] %[output:977cd030] %[output:04cba172]
%%
lambdaAE7=[370 470 520 590 660 880 950];
%compute abs exp
Ca3=startsWith(names_rd,{'Ba'}) & contains(names_rd,{'_A'});
names_abs=names_rd(Ca3);
VSK_cal=compute_exp_D(VSK_rd,names_abs,lambdaAE7); %[output:7c63b252] %[output:28094434]
plotFigControl_cal(VSK_cal,VSK_st.name); %[output:298f217f] %[output:26906365] %[output:99063df6]
%%
%HOMOGENEITY

break_VSK_abs_BP=change_point_analysis_Def(VSK_rd,names_abs,0.05,'VSK','Absorption'); %[output:6b7ee9f8] %[output:5a393386] %[output:85ed12d1] %[output:4eb1a59d] %[output:9f80f676] %[output:98c2ecf9]
T_VSK_abs_BP=make_table_breakpoints_def(break_VSK_abs_BP);

names_expA={'expA_bgAE','expA_brAE','expA_grAE','expA_fit'} %[output:50459008]
break_VSK_expA_BP=change_point_analysis_Def(VSK_cal,names_expA,0.05,'VSK','Absorption exponent'); %[output:10162b91] %[output:9a0fc507] %[output:519b713f] %[output:2ad9b22f]
T_VSK_expA_BP=make_table_breakpoints_def(break_VSK_expA_BP);




